  const quotes = [];
  for (let i = start + 1;i < lines.length; i++) {
    const line = lines[i].trim();
    if (HEADING.test(line))
      break;
    const quoted = line.match(/^>\s?(.*)$/);
    if (quoted && quoted[1].trim())
      quotes.push(quoted[1].trim());
  }
